insert into public.records (module, title, slug, status, data, published_at)
values ('services', $xt$Secure Architecture Review$xt$, 'secure-architecture-review', 'published', $xj${"summary": "Review how an application is designed to fail: trust boundaries, identity, data flow and tenant isolation.", "description": "Review how an application is designed to fail: trust boundaries, identity, data flow and tenant isolation.\n\n**Status:** Scoped per engagement. We confirm fit during the scoping call.", "category": "Application Security Engineering", "capability_group": "Engineering", "icon": "shield", "order": 10, "problem": "Design-level flaws survive code review and scanning. A missing authorization layer or an over-trusted internal service is expensive to fix after release.", "audience": "Engineering teams designing or scaling a SaaS product, API platform or web application.", "attack_paths": "- A service trusts another internal service without verifying the caller\n- Tenant identifiers are accepted from the client\n- Secrets and tokens share one trust boundary\n- Administrative functions reachable from user-facing paths", "methodology": "1. Collect architecture diagrams, authentication flows and data-store inventory.\n2. Model trust boundaries and the data that crosses them.\n3. Identify abuse paths from the perspective of each role.\n4. Rate each issue by exploitability and impact in your context.\n5. Recommend design changes your team can implement.", "example_scope": "Architecture documents, authentication and authorization flows, data stores, third-party integrations and deployment boundaries.", "process": "**1. Scoping call.** An engineer reviews your system and goals and confirms whether this service fits.\n\n**2. Written scope.** Assets, access, exclusions, timing and rules of engagement are agreed before any work starts.\n\n**3. Delivery.** Work proceeds with a named point of contact and agreed channels for urgent issues.\n\n**4. Readout.** Findings and recommendations are walked through with your engineers.\n\n**5. Verification.** Fixes can be retested against the original finding.", "retesting": "Fixes can be verified against the original finding. The result is recorded as resolved, partially resolved or still reproducible.", "deliverables": "- Written architecture review\n- Findings with rationale and severity\n- Prioritized design recommendations\n- Readout session with your engineers", "timeline": "Defined during scoping.", "features": "Trust boundary analysis\nAuthorization model review\nTenant isolation review\nData flow review", "testing_areas": "Identity and session design\nMulti-tenant boundaries\nService-to-service trust\nSecrets handling", "seo_title": "Secure Architecture Review for SaaS and APIs", "seo_description": "Review trust boundaries, identity, authorization and tenant isolation in your application design before attackers do.", "canonical_path": "/services/secure-architecture-review", "featured": false}$xj$::jsonb, now())
on conflict (module, slug) do nothing;
insert into public.records (module, title, slug, status, data, published_at)
values ('services', $xt$Vulnerability Remediation Engineering$xt$, 'vulnerability-remediation-engineering', 'published', $xj${"summary": "Fix the root cause of validated findings, with guidance written for the engineers who ship the change.", "description": "Fix the root cause of validated findings, with guidance written for the engineers who ship the change.\n\n**Status:** Xarmoured advises and verifies. Implementation stays with your team unless agreed in writing.", "category": "Application Security Engineering", "capability_group": "Engineering", "icon": "code", "order": 11, "problem": "Findings are often patched at the symptom. The same flaw returns in the next endpoint or release.", "audience": "Teams holding validated findings from any assessment who want durable fixes.", "attack_paths": "- A fix blocks one parameter while the flaw remains reachable another way\n- Authorization checked in the interface but not the backend\n- A patch that introduces a regression in access control", "methodology": "1. Review each finding and its reproduction.\n2. Trace the root cause in your design or code path.\n3. Propose a fix and the regression tests that protect it.\n4. Review the implemented change with your engineers.\n5. Retest the original attack path.", "example_scope": "Validated findings and the relevant application components, supplied by your team.", "process": "**1. Scoping call.** An engineer reviews your system and goals and confirms whether this service fits.\n\n**2. Written scope.** Assets, access, exclusions, timing and rules of engagement are agreed before any work starts.\n\n**3. Delivery.** Work proceeds with a named point of contact and agreed channels for urgent issues.\n\n**4. Readout.** Findings and recommendations are walked through with your engineers.\n\n**5. Verification.** Fixes can be retested against the original finding.", "retesting": "Fixes can be verified against the original finding. The result is recorded as resolved, partially resolved or still reproducible.", "deliverables": "- Root-cause analysis per finding\n- Remediation guidance and test suggestions\n- Review of the implemented fix\n- Retest result", "timeline": "Defined during scoping.", "features": "Root-cause analysis\nFix review\nRegression test guidance\nRetest verification", "testing_areas": "Access control fixes\nInput handling fixes\nSession and token fixes", "seo_title": "Vulnerability Remediation Engineering", "seo_description": "Root-cause remediation guidance and verification for validated security findings.", "canonical_path": "/services/vulnerability-remediation-engineering", "featured": false}$xj$::jsonb, now())
on conflict (module, slug) do nothing;
insert into public.records (module, title, slug, status, data, published_at)
values ('services', $xt$LLM Application Security Assessment$xt$, 'llm-application-security-assessment', 'published', $xj${"summary": "Assess applications built on large language models for prompt injection, data exposure and excessive agency.", "description": "Assess applications built on large language models for prompt injection, data exposure and excessive agency.\n\n**Status:** Emerging and research-stage. Engagements are scoped carefully and the limits of current methods are stated in the report.", "category": "AI Security", "capability_group": "Emerging Technology", "icon": "shield", "order": 20, "problem": "LLM features add inputs and behaviors that conventional testing does not cover: untrusted text can steer the model, and model output can reach sensitive actions.", "audience": "Teams shipping chat, copilot, summarization or content features backed by an LLM.", "attack_paths": "- Direct and indirect prompt injection\n- Model output passed to a database, browser or tool without validation\n- Sensitive data included in prompts or responses\n- Excessive permissions granted to the model", "methodology": "1. Map the application, model, data sources and tools.\n2. Test prompt injection against each input path.\n3. Test how model output is used downstream.\n4. Test data exposure across users and tenants.\n5. Report with reproducible prompts and recommended controls.\nThe OWASP Top 10 for LLM Applications is used as a reference framework.", "example_scope": "The LLM-backed feature, its system prompt where shared, data sources, connected tools and the surrounding API.", "process": "**1. Scoping call.** An engineer reviews your system and goals and confirms whether this service fits.\n\n**2. Written scope.** Assets, access, exclusions, timing and rules of engagement are agreed before any work starts.\n\n**3. Delivery.** Work proceeds with a named point of contact and agreed channels for urgent issues.\n\n**4. Readout.** Findings and recommendations are walked through with your engineers.\n\n**5. Verification.** Fixes can be retested against the original finding.", "retesting": "Fixes can be verified against the original finding. The result is recorded as resolved, partially resolved or still reproducible.", "deliverables": "- Findings with reproducible prompts\n- Impact in your application context\n- Recommended controls\n- Retest result", "timeline": "Defined during scoping.", "features": "Prompt injection testing\nOutput handling review\nData exposure testing\nAgency and permission review", "testing_areas": "Direct prompt injection\nIndirect prompt injection\nInsecure output handling\nExcessive agency", "seo_title": "LLM Application Security Assessment (Emerging)", "seo_description": "Research-stage security assessment of LLM applications: prompt injection, output handling, data exposure and agency.", "canonical_path": "/services/llm-application-security-assessment", "featured": false}$xj$::jsonb, now())
on conflict (module, slug) do nothing;
insert into public.records (module, title, slug, status, data, published_at)
values ('services', $xt$AI Agent and RAG Security Assessment$xt$, 'ai-agent-rag-security-assessment', 'published', $xj${"summary": "Assess retrieval-augmented generation and tool-using agents for leakage, poisoning and permission abuse.", "description": "Assess retrieval-augmented generation and tool-using agents for leakage, poisoning and permission abuse.\n\n**Status:** Emerging and research-stage. Scoped per engagement with stated limits.", "category": "AI Security", "capability_group": "Emerging Technology", "icon": "network", "order": 21, "problem": "Retrieval and tool use connect a model to your data and systems. Weak boundaries there turn a text-based attack into data access or action.", "audience": "Teams building RAG search, knowledge assistants or agents that call tools and APIs.", "attack_paths": "- Retrieval returns another tenant’s documents\n- Poisoned content changes agent behavior\n- An agent tool runs with broader permissions than the user\n- Instructions hidden in retrieved content", "methodology": "1. Map data sources, retrieval path, tools and permissions.\n2. Test authorization at retrieval and at each tool call.\n3. Test poisoned and hidden-instruction content.\n4. Test whether actions can be triggered across trust boundaries.\n5. Report with reproducible evidence and controls.", "example_scope": "Retrieval pipeline, indexed data sources, agent tools, the permissions each runs with and the connected APIs.", "process": "**1. Scoping call.** An engineer reviews your system and goals and confirms whether this service fits.\n\n**2. Written scope.** Assets, access, exclusions, timing and rules of engagement are agreed before any work starts.\n\n**3. Delivery.** Work proceeds with a named point of contact and agreed channels for urgent issues.\n\n**4. Readout.** Findings and recommendations are walked through with your engineers.\n\n**5. Verification.** Fixes can be retested against the original finding.", "retesting": "Fixes can be verified against the original finding. The result is recorded as resolved, partially resolved or still reproducible.", "deliverables": "- Findings with reproducible evidence\n- Authorization gaps at retrieval and tool boundaries\n- Recommended controls\n- Retest result", "timeline": "Defined during scoping.", "features": "Retrieval authorization testing\nContent poisoning tests\nTool permission review\nCross-tenant leakage tests", "testing_areas": "RAG pipelines\nAgent tool use\nRetrieval authorization", "seo_title": "AI Agent and RAG Security Assessment (Emerging)", "seo_description": "Research-stage assessment of RAG pipelines and AI agents: retrieval authorization, poisoning and tool permission abuse.", "canonical_path": "/services/ai-agent-rag-security-assessment", "featured": false}$xj$::jsonb, now())
on conflict (module, slug) do nothing;
insert into public.records (module, title, slug, status, data, published_at)
values ('services', $xt$Security Automation Engineering$xt$, 'security-automation-engineering', 'published', $xj${"summary": "Turn manual security checks into repeatable automation your team can run on every release.", "description": "Turn manual security checks into repeatable automation your team can run on every release.\n\n**Status:** Scoped per engagement. We confirm feasibility during the scoping call.", "category": "Security Automation", "capability_group": "Engineering", "icon": "code", "order": 30, "problem": "Manual retests do not scale with release speed. Access-control and regression checks drift when nobody re-runs them.", "audience": "Engineering teams that want repeatable security checks in their delivery pipeline.", "attack_paths": "- An access-control fix regresses two releases later\n- Retest evidence exists only as screenshots\n- Security checks run only before a yearly assessment", "methodology": "1. Identify the checks worth repeating, usually from validated findings.\n2. Implement them as automated tests against a defined environment.\n3. Define pass and fail criteria with your team.\n4. Document how to run and maintain them.\n5. Review results after the first runs.", "example_scope": "Chosen findings or security requirements, a test environment, test accounts and your delivery pipeline.", "process": "**1. Scoping call.** An engineer reviews your system and goals and confirms whether this service fits.\n\n**2. Written scope.** Assets, access, exclusions, timing and rules of engagement are agreed before any work starts.\n\n**3. Delivery.** Work proceeds with a named point of contact and agreed channels for urgent issues.\n\n**4. Readout.** Findings and recommendations are walked through with your engineers.\n\n**5. Verification.** Fixes can be retested against the original finding.", "retesting": "Fixes can be verified against the original finding. The result is recorded as resolved, partially resolved or still reproducible.", "deliverables": "- Automated checks in your repository\n- Run and maintenance documentation\n- Pass and fail criteria\n- Review of first results", "timeline": "Defined during scoping.", "features": "Access-control regression checks\nRetest automation\nPipeline integration\nResult reporting", "testing_areas": "Authorization regression\nToken and session checks\nRelease gating", "seo_title": "Security Automation Engineering", "seo_description": "Repeatable security regression checks and retest automation for engineering teams.", "canonical_path": "/services/security-automation-engineering", "featured": false}$xj$::jsonb, now())
on conflict (module, slug) do nothing;
insert into public.records (module, title, slug, status, data, published_at)
values ('pages', $xt$ExploitLedger$xt$, 'platform', 'published', $xj${"headline": "ExploitLedger", "summary": "An AI-assisted vulnerability assessment and remediation management platform, in development at Xarmoured.", "content": "## What it is\n\nExploitLedger helps security teams run assessments and track findings through to verified remediation. It is built from our own assessment work.\n\n## Availability\n\nIn development. There is no public release, pricing or launch date. Demo and early-access conversations are handled by [enquiry](/assessment).\n\n## What is published\n\nThe features, workflow and conceptual architecture pages separate what the product does today from what is planned. No customer, integration or performance claims are made.", "seo_title": "ExploitLedger — vulnerability assessment and remediation platform | Xarmoured", "seo_description": "ExploitLedger is an AI-assisted vulnerability assessment and remediation management platform in development from Xarmoured.", "canonical_path": "/platform", "content_type": "landing"}$xj$::jsonb, now())
on conflict (module, slug) do nothing;
insert into public.records (module, title, slug, status, data, published_at)
values ('pages', $xt$ExploitLedger features$xt$, 'exploitledger-features', 'published', $xj${"headline": "ExploitLedger features", "summary": "What the platform manages today, and what is only planned.", "content": "## Existing functionality\n\n- Engagement management\n- Asset management\n- Vulnerability tracking\n- OWASP-based assessment workflows\n- Evidence management and integrity\n- CWE classification\n- CVSS scoring\n- Remediation tracking\n- Retesting workflows\n- Organizational separation and access control\n\n## Planned or not yet specified\n\n- AI assistance: part of the product direction. Specific AI features are not yet published and are not claimed here.\n- Integrations, reporting exports and deployment options: not yet published.\n\n## Screenshots\n\nProduct screenshots are not yet published. They will be added here when they are available.\n\n[Request a demo](/assessment)", "seo_title": "ExploitLedger features | Xarmoured", "seo_description": "Engagement and asset management, vulnerability tracking, evidence integrity, CWE and CVSS, remediation tracking and retesting in ExploitLedger.", "canonical_path": "/exploitledger-features", "content_type": "landing"}$xj$::jsonb, now())
on conflict (module, slug) do nothing;
insert into public.records (module, title, slug, status, data, published_at)
values ('pages', $xt$ExploitLedger workflow$xt$, 'exploitledger-workflow', 'published', $xj${"headline": "ExploitLedger workflow", "summary": "From engagement to verified remediation.", "content": "## The workflow\n\n**Engagement.** Create the engagement and define scope.\n\n**Assets.** Register the assets in scope.\n\n**Assessment.** Work through an OWASP-based assessment workflow.\n\n**Findings.** Record each vulnerability with CWE classification and CVSS scoring.\n\n**Evidence.** Attach evidence and keep its integrity.\n\n**Remediation.** Track each fix to completion.\n\n**Retest.** Retest and record whether the issue is closed.\n\nWork is separated by organization with access control throughout.\n\nThis page describes the workflow supported by the listed capabilities. See [features](/exploitledger-features) for what is planned.", "seo_title": "ExploitLedger workflow | Xarmoured", "seo_description": "How ExploitLedger carries an assessment from engagement and evidence to remediation tracking and retesting.", "canonical_path": "/exploitledger-workflow", "content_type": "landing"}$xj$::jsonb, now())
on conflict (module, slug) do nothing;
insert into public.records (module, title, slug, status, data, published_at)
values ('pages', $xt$ExploitLedger architecture$xt$, 'exploitledger-architecture', 'published', $xj${"headline": "ExploitLedger architecture", "summary": "The conceptual model behind the platform.", "content": "## Conceptual model\n\nThis is a domain overview, not a deployment diagram.\n\n- **Organization:** the boundary for data and access control.\n- **Engagement:** a scoped assessment inside an organization.\n- **Asset:** a system in scope for an engagement.\n- **Vulnerability:** a finding on an asset, with CWE and CVSS.\n- **Evidence:** material that supports a finding, with integrity protection.\n- **Remediation and retest:** the fix and its verification.\n\n## Not yet published\n\nHosting, data handling, integrations and security controls of the platform itself are not yet published. We will add them when they are final.", "seo_title": "ExploitLedger architecture overview | Xarmoured", "seo_description": "The conceptual data model of ExploitLedger: organizations, engagements, assets, vulnerabilities, evidence and remediation.", "canonical_path": "/exploitledger-architecture", "content_type": "landing"}$xj$::jsonb, now())
on conflict (module, slug) do nothing;
insert into public.records (module, title, slug, status, data, published_at)
values ('pages', $xt$Engineering philosophy$xt$, 'engineering-philosophy', 'published', $xj${"headline": "Engineering philosophy", "summary": "How offensive testing, research and software work together.", "content": "## Depth over checklists\n\nWe explore business logic, authorization boundaries and the interaction between components.\n\n## Evidence over assumptions\n\nWe validate behavior, document the conditions and state the limits of every assessment.\n\n## Resolution over volume\n\nA finding is useful when engineers can fix its cause. We then test the fix.\n\n## One loop\n\nAttack research informs testing. Testing informs remediation. Remediation informs the software we build.\n\nXarmoured is independent and founder-led.", "seo_title": "Engineering philosophy | Xarmoured", "seo_description": "Depth over checklists, evidence over assumptions, resolution over volume: how Xarmoured approaches security engineering.", "canonical_path": "/engineering-philosophy", "content_type": "landing"}$xj$::jsonb, now())
on conflict (module, slug) do nothing;
insert into public.records (module, title, slug, status, data, published_at)
values ('pages', $xt$Research approach$xt$, 'research-approach', 'published', $xj${"headline": "Research approach", "summary": "How we research, disclose and publish.", "content": "## What we research\n\nVulnerability research, CVE disclosures, security advisories, AI security research, technical publications and open source tools.\n\n## Disclosure\n\nResearch is published only after disclosure is public. Affected vendors are given the chance to fix first. See [responsible disclosure](/security).\n\n## Attribution\n\nEvery entry names the researcher and links to official sources such as advisories and CVE records.\n\n## Where to read it\n\nBrowse the [research listing](/research).", "seo_title": "Research approach | Xarmoured", "seo_description": "How Xarmoured researches vulnerabilities, coordinates disclosure and attributes published work.", "canonical_path": "/research-approach", "content_type": "landing"}$xj$::jsonb, now())
on conflict (module, slug) do nothing;
insert into public.records (module, title, slug, status, data, published_at)
values ('pages', $xt$Partnerships$xt$, 'partnerships', 'published', $xj${"headline": "Partnerships", "summary": "Working with other security and technology teams.", "content": "## Where collaboration makes sense\n\n- Research collaboration on attack techniques and disclosures\n- Technology partners whose products complement assessment and remediation work\n- Security firms that need specialist application testing capacity\n\n## Current partners\n\nNone are listed. We will name a partner here only with their agreement.\n\n## Start a conversation\n\nUse the [contact form](/contact) and select the partnership enquiry topic.", "seo_title": "Partnerships | Xarmoured", "seo_description": "Research, technology and services partnerships with Xarmoured. No partners are listed until agreed.", "canonical_path": "/partnerships", "content_type": "landing"}$xj$::jsonb, now())
